package com.powercms.cms.delivery.navigation;
import com.powercms.cms.audit.AuditService; import com.powercms.cms.delivery.RenderDatasetCache; import com.powercms.common.error.*; import org.springframework.dao.OptimisticLockingFailureException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; import java.util.regex.*;
@Service @Transactional public class UrlRewriteService {
 private static final int MAX_HOPS=8,MAX_PATTERN=512; private static final List<String> RESERVED=List.of("/api","/actuator","/admin"); private final UrlRewriteRuleRepository repo;private final RenderDatasetCache cache;private final AuditService audit;
 public UrlRewriteService(UrlRewriteRuleRepository r,RenderDatasetCache c,AuditService a){repo=r;cache=c;audit=a;}
 public record Info(UUID id,String name,String pattern,String replacement,int priority,String status,long lockVersion){} public record Validation(boolean valid,List<String> errors){} public record TestResult(String input,String output,int hops,List<String> rules){}
 public List<Info> list(UUID siteId){return repo.findBySiteIdOrderByPriorityDescNameAsc(siteId).stream().map(this::info).toList();}
 public Validation validate(UUID siteId,UUID id,String name,String pattern,String replacement,int priority){List<String> e=new ArrayList<>();if(name==null||name.isBlank()||name.length()>200)e.add("名称必填且不超过 200 字符");validatePattern(pattern,e);validateTarget(replacement,e);if(name!=null&&(id==null?repo.existsBySiteIdAndName(siteId,name):repo.existsBySiteIdAndNameAndIdNot(siteId,name,id)))e.add("规则名称已存在");if(pattern!=null)for(var r:repo.findBySiteIdOrderByPriorityDescNameAsc(siteId))if(!Objects.equals(r.getId(),id)&&r.getPriority()==priority&&r.getPattern().equals(pattern))e.add("同一优先级下 pattern 重复");return new Validation(e.isEmpty(),List.copyOf(e));}
 public Info save(UUID siteId,UUID id,String name,String pattern,String replacement,int priority,String status,Long lock,String actor){Validation v=validate(siteId,id,name,pattern,replacement,priority);if(!v.valid())throw bad(String.join("; ",v.errors()));UrlRewriteRuleEntity x=id==null?new UrlRewriteRuleEntity():repo.findByIdAndSiteId(id,siteId).orElseThrow(()->new BusinessException(ErrorCodes.NOT_FOUND,"重写规则不存在"));if(id!=null&&lock!=null&&x.getLockVersion()!=lock)throw new BusinessException(ErrorCodes.CONFLICT,"重写规则已被他人修改，请刷新后重试");x.setSiteId(siteId);x.setName(name.trim());x.setPattern(pattern);x.setReplacement(replacement);x.setPriority(priority);x.setStatus("ACTIVE".equalsIgnoreCase(status)?"ACTIVE":"DRAFT");x.setCreatedBy(actor);try{x=repo.saveAndFlush(x);}catch(OptimisticLockingFailureException ex){throw new BusinessException(ErrorCodes.CONFLICT,"重写规则已被他人修改，请刷新后重试");}cache.invalidatePrefix(RenderDatasetCache.Region.SCRIPT,"rewrite:"+siteId);audit.write(actor,"URL_REWRITE_SAVE","URL_REWRITE_RULE",x.getId().toString(),siteId,"SUCCESS",null);return info(x);}
 public void delete(UUID siteId,UUID id,String actor){var x=repo.findByIdAndSiteId(id,siteId).orElseThrow(()->new BusinessException(ErrorCodes.NOT_FOUND,"重写规则不存在"));repo.delete(x);cache.invalidatePrefix(RenderDatasetCache.Region.SCRIPT,"rewrite:"+siteId);audit.write(actor,"URL_REWRITE_DELETE","URL_REWRITE_RULE",id.toString(),siteId,"SUCCESS",null);}
 @Transactional(readOnly=true) public String rewrite(UUID siteId,String input,boolean preview){return test(siteId,input,preview).output();}
 @Transactional(readOnly=true) public TestResult test(UUID siteId,String input,boolean preview){String current=normalize(input);if(reserved(current))return new TestResult(input,current,0,List.of());List<String> applied=new ArrayList<>();Set<String> seen=new HashSet<>();seen.add(current);List<UrlRewriteRuleEntity> rules=cache.getOrLoad(RenderDatasetCache.Region.SCRIPT,"rewrite:"+siteId,!preview,()->repo.findBySiteIdOrderByPriorityDescNameAsc(siteId).stream().filter(x->"ACTIVE".equals(x.getStatus())).toList());for(int hop=0;hop<MAX_HOPS;hop++){String next=current;String ruleName=null;for(var r:rules){Matcher m=Pattern.compile(r.getPattern()).matcher(current);if(m.matches()){next=m.replaceFirst(r.getReplacement());validateTargetOrThrow(next);ruleName=r.getName();break;}}if(next.equals(current))return new TestResult(input,current,applied.size(),List.copyOf(applied));if(reserved(next))throw bad("重写结果命中保留路径，禁止循环重写");if(!seen.add(next))throw new BusinessException(ErrorCodes.CONFLICT,"URL 重写检测到循环");applied.add(ruleName);current=next;}throw new BusinessException(ErrorCodes.CONFLICT,"URL 重写超过最大跳数 "+MAX_HOPS);}
 static void validatePattern(String p,List<String> e){if(p==null||p.isBlank()||p.length()>MAX_PATTERN){e.add("pattern required, max 512");return;}if(!p.startsWith("^")||!p.endsWith("$"))e.add("pattern must be anchored with ^ and $");String[] dangerous={".*.*",".+.+","++","*+","(?=","(?!","(?<=","(?<!","\\1"};for(String token:dangerous)if(p.contains(token))e.add("pattern contains a prohibited ReDoS/advanced construct");if(Pattern.compile("\\([^)]*[+*][^)]*\\)[+*?]").matcher(p).find())e.add("nested quantifiers are prohibited");try{Pattern.compile(p);}catch(PatternSyntaxException ex){e.add("invalid regular expression");}}
 static void validateTarget(String r,List<String> e){try{validateTargetOrThrow(r);}catch(BusinessException x){e.add(x.getMessage());}} static void validateTargetOrThrow(String r){if(r==null||r.isBlank()||r.length()>1000||!r.startsWith("/")||r.startsWith("//")||r.contains("..")||r.indexOf('\\')>=0||r.chars().anyMatch(Character::isISOControl))throw bad("replacement must be a safe site-relative path");}
 static boolean reserved(String p){return RESERVED.stream().anyMatch(x->p.equals(x)||p.startsWith(x+"/"));} static String normalize(String p){if(p==null||p.isBlank())return "/";String x=p.trim();if(!x.startsWith("/"))x="/"+x;if(x.contains("..")||x.indexOf('\\')>=0||x.chars().anyMatch(Character::isISOControl))throw bad("invalid path");return x;} private Info info(UrlRewriteRuleEntity x){return new Info(x.getId(),x.getName(),x.getPattern(),x.getReplacement(),x.getPriority(),x.getStatus(),x.getLockVersion());} private static BusinessException bad(String m){return new BusinessException(ErrorCodes.VALIDATION_FAILED,m);}
}
